// Checklist pages: checks/*.txt, one per RE/20 live check (generated by tools/gen_checks.py, editable by hand).
//   id: 39
//   title: Ledge stop at the edge line
//   script: scripts/walk_60s.txt        (optional: an input script the check can run by itself, F11)
//   steps:
//     Walk slowly toward a roof edge ...
//   probes:
//     0xD93C60 LedgeStop_Enter feet=$entity+0x40:vec3
//   fields:
//     hg_state=$hg+0x5E8:f32
// Selecting a page arms its probes (plus probes/always.txt) and adds its fields to every recorded frame.
#include "lab.h"
#include <stdlib.h>
#include <string.h>

static LabCheck g_checks[LAB_MAX_CHECKS];
static int g_n, g_cur = -1;
static char g_names[LAB_MAX_FIELDS][48], g_exprs[LAB_MAX_FIELDS][160];
static volatile LONG g_nfields;
static CRITICAL_SECTION g_cs;

static void append(char *dst, size_t n, const char *line)
{
    if (dst[0]) strcat_s(dst, n, "\n");
    strcat_s(dst, n, line);
}

static void parse(const char *path, LabCheck *c)
{
    FILE *f;
    char line[1024];
    char *block = NULL;
    size_t blen = 0;
    memset(c, 0, sizeof(*c));
    if (fopen_s(&f, path, "r")) return;
    while (fgets(line, sizeof(line), f)) {
        char *p = line, *nl = strpbrk(line, "\r\n");
        int indented = line[0] == ' ' || line[0] == '\t';
        if (nl) *nl = 0;
        while (*p == ' ' || *p == '\t') p++;
        if (!indented) {
            block = NULL;
            if (!strncmp(p, "id:", 3)) { p += 3; while (*p == ' ') p++; strcpy_s(c->id, sizeof(c->id), p); }
            else if (!strncmp(p, "title:", 6)) { p += 6; while (*p == ' ') p++; strcpy_s(c->title, sizeof(c->title), p); }
            else if (!strncmp(p, "script:", 7)) {
                p += 7;
                while (*p == ' ') p++;
                if (*p) sprintf_s(c->auto_script, MAX_PATH, "%s\\%s", g_lab.dir, p);
            }
            else if (!strncmp(p, "steps:", 6)) block = c->steps, blen = sizeof(c->steps);
            else if (!strncmp(p, "probes:", 7)) block = c->probes, blen = sizeof(c->probes);
            else if (!strncmp(p, "fields:", 7)) block = c->fields, blen = sizeof(c->fields);
        } else if (block && *p) {
            append(block, blen, p);
        }
    }
    fclose(f);
}

static int cmp_check(const void *a, const void *b)
{
    return atoi(((const LabCheck *)a)->id) - atoi(((const LabCheck *)b)->id);
}

void checks_load(void)
{
    char pattern[MAX_PATH], path[MAX_PATH];
    WIN32_FIND_DATAA fd;
    HANDLE h;
    static int cs_ready;
    if (!cs_ready) { InitializeCriticalSection(&g_cs); cs_ready = 1; }
    g_n = 0;
    g_cur = -1;
    sprintf_s(pattern, MAX_PATH, "%s\\checks\\*.txt", g_lab.dir);
    h = FindFirstFileA(pattern, &fd);
    if (h != INVALID_HANDLE_VALUE) {
        do {
            if (g_n >= LAB_MAX_CHECKS) break;
            sprintf_s(path, MAX_PATH, "%s\\checks\\%s", g_lab.dir, fd.cFileName);
            parse(path, &g_checks[g_n]);
            if (g_checks[g_n].id[0]) g_n++;
        } while (FindNextFileA(h, &fd));
        FindClose(h);
    }
    qsort(g_checks, g_n, sizeof(LabCheck), cmp_check);
    lab_log("%d checks loaded", g_n);
    checks_select(0);
}

int checks_count(void) { return g_n; }

const LabCheck *checks_current(void) { return g_cur >= 0 && g_cur < g_n ? &g_checks[g_cur] : NULL; }

static void apply(void)
{
    char path[MAX_PATH], buf[4096];
    FILE *f;
    const LabCheck *c = checks_current();
    probes_clear();
    sprintf_s(path, MAX_PATH, "%s\\probes\\always.txt", g_lab.dir);
    if (!fopen_s(&f, path, "r")) {
        size_t n = fread(buf, 1, sizeof(buf) - 1, f);
        buf[n] = 0;
        fclose(f);
        probes_load_text(buf, "always.txt");
    }
    EnterCriticalSection(&g_cs);
    g_nfields = 0;
    if (c) {
        probes_load_text(c->probes, c->id);
        g_nfields = expr_split_fields(c->fields, g_names, g_exprs, LAB_MAX_FIELDS);
    }
    LeaveCriticalSection(&g_cs);
    if (c) {
        lab_log("check %s: %s (%d probes, %ld fields)", c->id, c->title, probes_count(), g_nfields);
        overlay_note("check %s", c->id);
    }
}

void checks_select(int delta)
{
    if (!g_n) { g_cur = -1; apply(); return; }
    if (g_cur < 0) g_cur = 0;
    else g_cur = (g_cur + delta + g_n) % g_n;
    if (trace_active()) trace_stop();
    apply();
}

void checks_select_id(const char *id)
{
    int i;
    for (i = 0; i < g_n; i++)
        if (atoi(g_checks[i].id) == atoi(id)) {
            g_cur = i;
            if (trace_active()) trace_stop();
            apply();
            return;
        }
}

void checks_fields(char names[][48], char exprs[][160], int *n)
{
    int i;
    EnterCriticalSection(&g_cs);
    for (i = 0; i < g_nfields; i++) {
        strcpy_s(names[i], 48, g_names[i]);
        strcpy_s(exprs[i], 160, g_exprs[i]);
    }
    *n = g_nfields;
    LeaveCriticalSection(&g_cs);
}

// Fields added at run time (bridge "field add name=expr", "field clear"): appended to the page's until it changes.
void checks_field_add(const char *line)
{
    EnterCriticalSection(&g_cs);
    if (g_nfields < LAB_MAX_FIELDS) {
        char names[1][48], exprs[1][160];
        if (expr_split_fields(line, names, exprs, 1) == 1) {
            strcpy_s(g_names[g_nfields], 48, names[0]);
            strcpy_s(g_exprs[g_nfields], 160, exprs[0]);
            g_nfields++;
        }
    }
    LeaveCriticalSection(&g_cs);
}

void checks_field_clear(void)
{
    EnterCriticalSection(&g_cs);
    g_nfields = 0;
    LeaveCriticalSection(&g_cs);
}
